qs.append({"q":"The Moderate leaders of the INC (1885-1905), such as Dadabhai Naoroji, Pherozshah Mehta and S.N. Banerjea, primarily relied on which method of political activity?","o":["Constitutional agitation through prayer, petition and public opinion within the confines of law","Armed insurrection against British authorities","Boycott of all British goods and institutions","Direct appeal to foreign powers for military intervention"],"a":0,"e":"The Moderates believed in constitutional methods — creating public opinion, and using petitions and resolutions — believing that the British would gradually concede reforms."})

